// scanMetrics reads all rows into a MetricFamily, grouping metric points by
// service (and operation when groupByOperation is set) while preserving the
// order in which each group is first encountered.
func scanMetrics(rows driver.Rows, name string, groupByOperation bool) (*metrics.MetricFamily, error) {
	type groupKey struct {
		service   string
		operation string
	}

	var order []groupKey
	byKey := make(map[groupKey]*metrics.Metric)

	for rows.Next() {
		var row metricsRow
		if err := rows.ScanStruct(&row); err != nil {
			return nil, fmt.Errorf("failed to scan metrics row: %w", err)
		}

		key := groupKey{service: row.ServiceName}
		if groupByOperation {
			key.operation = row.Operation
		}

		metric, ok := byKey[key]
		if !ok {
			labels := []*metrics.Label{
				{Name: "service_name", Value: row.ServiceName},
			}
			if groupByOperation {
				labels = append(labels, &metrics.Label{Name: "operation", Value: row.Operation})
			}
			metric = &metrics.Metric{Labels: labels}
			byKey[key] = metric
			order = append(order, key)
		}

		metric.MetricPoints = append(metric.MetricPoints, toMetricPoint(row.Timestamp, row.Value))
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating metrics rows: %w", err)
	}

	family := &metrics.MetricFamily{
		Name: name,
		Type: metrics.MetricType_GAUGE,
	}
	for _, key := range order {
		family.Metrics = append(family.Metrics, byKey[key])
	}
