// stepSeconds converts BaseQueryParameters.Step to a whole number of seconds.
// A nil, zero, or negative Step yields defaultStepSeconds. A positive sub-second
// Step is clamped to 1, and fractional seconds are truncated.
func stepSeconds(p metricstore.BaseQueryParameters) uint64 {
	if p.Step == nil || *p.Step <= 0 {
		return defaultStepSeconds
	}
	seconds := uint64(*p.Step / time.Second)
	if seconds == 0 {
		return 1
	}
	return seconds
}

