// stored in ClickHouse. Unrecognized kinds are omitted from the result.
func convertSpanKinds(kinds []string) []string {
	converted := make([]string, 0, len(kinds))
	for _, kind := range kinds {
		if mapped, ok := spanKindMapping[kind]; ok {
			converted = append(converted, mapped)
		}
	}
	return converted
}
